package com.example.spring_blog.admin;import com.example.spring_blog.error.Exception403;import com.example.spring_blog.user.SessionUserDTO;import com.example.spring_blog.util.Define;import jakarta.servlet.http.HttpSession;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.GetMapping;@Controllerpublic class AdminController {    @GetMapping("/admin/dashboard")    public String dashboard(Model model, HttpSession session) {        SessionUserDTO sessionUserDTO = (SessionUserDTO) session.getAttribute(Define.SESSION_USER);        if (!sessionUserDTO.isAdmin()) {            throw new Exception403("권한없음");        }        model.addAttribute("adminName", sessionUserDTO.getUsername());        return "admin/dashboard";    }}